=== AutoClosePeriods
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** After the sheet's today is set: with grace days set, closes every open period whose to-date plus
 *  the grace days is before the new today, in order of their to-dates, as a close by hand does, each
 *  recorded as PERIOD_CLOSED with auto=yes. */
public class AutoClosePeriods {
    public void close(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, ClaimLogRepository log, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, Audit audit) {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        String grace = settings.find(id, SettingRepository.GRACE_DAYS);
        if (grace == null) return;
        LocalDate today = sheets.today(id);
        int days = Integer.parseInt(grace);
        for (Period found : periods.list(id).stream().sorted(Comparator.comparing(Period::to)).toList()) {
            if (found.closed() || !LocalDate.parse(found.to()).plusDays(days).isBefore(today)) continue;
            Period closed = PeriodClosing.closeNow(found, user, periods, claims, log, people, rates, settings, sheets);
            audit.record("PERIOD_CLOSED sheet=" + id + " by=" + user + " period=" + closed.name()
                    + " total=" + closed.closedTotal() + " auto=yes");
        }
    }
}
# POST /api/sheets/{sheetId}/periods/{name}/close — close a period, fixing its due-total; refused
# (409) when it is already closed, and (403) for a role the permission matrix does not let close.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# POST /api/sheets/{sheetId}/periods/{name}/reopen — reopen a closed period, making its due-total
# live again; refused (409) for anyone but a steward, or when it is not closed.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodReopened
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
-- The sheet's periods: a name (unique on the sheet, compared without regard to case; stored trimmed)
-- and a from and to date, inclusive, from on or before to. No two periods on a sheet overlap (checked
-- when one is added). A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name       VARCHAR(200) NOT NULL,
    name_key   VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date  DATE         NOT NULL,
    to_date    DATE         NOT NULL,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A closed period: its due-total is fixed at the moment it was closed (closed_total), and no claim
-- dated inside it can be added, edited, opened, settled or voided. Open until closed.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
